1	// pattern: Mixed (unavoidable)
2	//
3	// Gathers: a URL-shaped OAuth client_id + the shared outbound HTTP client
4	// Processes: URL policy validation (pure) → metadata-document fetch (shell) →
5	//            document validation (pure)
6	// Returns: the raw client-metadata JSON for the caller to cache, or a typed refusal
7	//
8	// ATProto OAuth clients identify themselves by the URL of their client-metadata
9	// document; authorization servers resolve unknown client_ids by fetching that URL
10	// (https://atproto.com/specs/oauth). This module is that resolver. The fetched URL is
11	// caller-controlled, so the policy check runs before any network I/O: https is
12	// required everywhere except loopback hosts, which may use plain http (the spec's
13	// local-development exception — also what lets tests serve metadata from 127.0.0.1).
14	
15	use url::{Host, Url};
16	
17	/// Upper bound on an accepted client-metadata document. Real documents are well under
18	/// 4 KiB; the cap only exists so a hostile URL can't stream an unbounded body into memory.
19	const MAX_METADATA_BYTES: usize = 64 * 1024;
20	
21	/// Fetch timeout for the metadata document, independent of (and tighter than) the shared
22	/// client's default: PAR is interactive and a slow metadata host shouldn't hold it long.
23	const FETCH_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(5);
24	
25	/// Why a URL client_id could not be resolved to a usable client-metadata document.
26	///
27	/// The `Display` text becomes the OAuth `error_description`, so each message names the
28	/// problem from the client developer's point of view.
29	#[derive(Debug, thiserror::Error)]
30	pub enum ClientResolutionError {
31	    #[error("client_id is not a valid URL")]
32	    InvalidUrl,
33	
34	    #[error("client_id must be an https URL (plain http is allowed for loopback hosts only)")]
35	    InsecureUrl,
36	
37	    #[error("client_id URL must not contain credentials or a fragment")]
38	    ForbiddenUrlParts,
39	
40	    #[error("failed to fetch client metadata: {0}")]
41	    Fetch(String),
42	
43	    #[error("client metadata document exceeds {MAX_METADATA_BYTES} bytes")]
44	    TooLarge,
45	
46	    #[error("client metadata document is not valid JSON")]
47	    InvalidJson,
48	
49	    #[error(
50	        "client metadata client_id mismatch (the document must declare the URL it is served from)"
51	    )]
52	    ClientIdMismatch,
53	}
54	
55	/// Validate the URL policy for a metadata-URL client_id (pure; no I/O).
56	///
57	/// Rules: parseable; https (http only for loopback hosts); no userinfo; no fragment.
58	fn validate_client_id_url(client_id: &str) -> Result<Url, ClientResolutionError> {
59	    let url = Url::parse(client_id).map_err(|_| ClientResolutionError::InvalidUrl)?;
60	
61	    match url.scheme() {
62	        "https" => {}
63	        "http" if host_is_loopback(&url) => {}
64	        _ => return Err(ClientResolutionError::InsecureUrl),
65	    }
66	
67	    if !url.username().is_empty() || url.password().is_some() || url.fragment().is_some() {
68	        return Err(ClientResolutionError::ForbiddenUrlParts);
69	    }
70	
71	    Ok(url)
72	}
73	
74	fn host_is_loopback(url: &Url) -> bool {
75	    match url.host() {
76	        Some(Host::Domain(d)) => d.eq_ignore_ascii_case("localhost"),
77	        Some(Host::Ipv4(ip)) => ip.is_loopback(),
78	        Some(Host::Ipv6(ip)) => ip.is_loopback(),
79	        None => false,
80	    }
81	}
82	
83	/// Whether a URL string's host is loopback (pure; unparseable → false). Shared policy
84	/// point: loopback is the one place plain-http client_ids and locally-derived (rather
85	/// than canonical) wallet client_ids are acceptable.
86	pub(crate) fn url_is_loopback(url: &str) -> bool {
87	    Url::parse(url)
88	        .map(|u| host_is_loopback(&u))
89	        .unwrap_or(false)
90	}
