92	/// Validate a fetched metadata document against the client_id it was fetched from (pure).
93	///
94	/// Per the ATProto OAuth spec the document MUST declare its own URL as `client_id` —
95	/// this is what stops one origin from impersonating another origin's client.
96	fn validate_metadata_document(client_id: &str, body: &str) -> Result<(), ClientResolutionError> {
97	    let doc: serde_json::Value =
98	        serde_json::from_str(body).map_err(|_| ClientResolutionError::InvalidJson)?;
99	
100	    if doc.get("client_id").and_then(|v| v.as_str()) != Some(client_id) {
101	        return Err(ClientResolutionError::ClientIdMismatch);
102	    }
103	
104	    Ok(())
105	}
106	
107	/// Resolve a URL client_id to its raw client-metadata JSON (validate URL → fetch →
108	/// validate document). The caller decides whether/when to cache the returned JSON.
109	pub async fn resolve_client_metadata(
110	    http: &reqwest::Client,
111	    client_id: &str,
112	) -> Result<String, ClientResolutionError> {
113	    let url = validate_client_id_url(client_id)?;
114	
115	    let response = http
116	        .get(url)
117	        .header("Accept", "application/json")
118	        .timeout(FETCH_TIMEOUT)
119	        .send()
120	        .await
121	        .map_err(|e| ClientResolutionError::Fetch(e.to_string()))?;
122	
123	    let status = response.status();
124	    if !status.is_success() {
125	        return Err(ClientResolutionError::Fetch(format!("HTTP {status}")));
126	    }
127	
128	    if response
129	        .content_length()
130	        .is_some_and(|l| l > MAX_METADATA_BYTES as u64)
131	    {
132	        return Err(ClientResolutionError::TooLarge);
133	    }
134	
135	    let body = response
136	        .bytes()
137	        .await
138	        .map_err(|e| ClientResolutionError::Fetch(e.to_string()))?;
139	    if body.len() > MAX_METADATA_BYTES {
140	        return Err(ClientResolutionError::TooLarge);
141	    }
142	
143	    let body = String::from_utf8(body.to_vec()).map_err(|_| ClientResolutionError::InvalidJson)?;
144	    validate_metadata_document(client_id, &body)?;
145	
146	    Ok(body)
147	}
