266	/// `GET /oauth/authorize` — validate request parameters and render the consent page.
267	///
268	/// Accepts either direct query parameters or a PAR `request_uri` (RFC 9126).
269	/// Returns an HTML error page (400) for errors that make a redirect unsafe:
270	/// unknown `client_id` or mismatched `redirect_uri`. All other parameter errors
271	/// redirect to `redirect_uri` with an `error` query parameter per RFC 6749 §4.1.2.1.
272	pub async fn get_authorization(
273	    State(state): State<AppState>,
274	    headers: HeaderMap,
275	    Query(raw): Query<GetAuthorizationQuery>,
276	) -> Response {
277	    // RFC 9207 issuer identifier, emitted as `iss` on every authorization response.
278	    // Trailing slash trimmed to match the AS-metadata `issuer` value exactly.
279	    let issuer = state.config.public_url.trim_end_matches('/').to_string();
280	    let params = match resolve_authorize_params(&state, raw).await {
281	        Ok(p) => p,
282	        Err(ResolveError::Client(msg)) => {
283	            return error_page("Invalid Request", msg).into_response()
284	        }
285	        Err(ResolveError::Server(msg)) => return error_page("Server Error", msg).into_response(),
286	    };
287	
288	    // Client and redirect_uri must be validated before any redirect is issued.
289	    let metadata =
290	        match lookup_and_validate_client(&state, &params.client_id, &params.redirect_uri).await {
291	            Ok(m) => m,
292	            Err(ClientValidationError::UnknownClient) => {
293	                return error_page(
294	                    "Unknown Client",
295	                    "The client_id is not registered with this server.",
296	                )
297	                .into_response()
298	            }
299	            Err(ClientValidationError::DbError) => {
300	                return error_page(
301	                    "Server Error",
302	                    "A database error occurred. Please try again.",
303	                )
304	                .into_response()
305	            }
306	            Err(ClientValidationError::MalformedMetadata) => {
307	                return error_page(
308	                    "Client Configuration Error",
309	                    "The client's registered metadata is malformed.",
310	                )
311	                .into_response()
312	            }
313	            Err(ClientValidationError::InvalidRedirectUri) => {
314	                return error_page(
315	                    "Invalid Redirect URI",
316	                    "The redirect_uri does not match the client's registered URIs.",
317	                )
318	                .into_response()
319	            }
320	        };
321	
322	    // From here on redirect_uri is validated — errors redirect there, not to an error page.
323	    if params.response_type != "code" {
324	        return error_redirect(
325	            &params.redirect_uri,
326	            "unsupported_response_type",
327	            "only response_type=code is supported",
328	            &params.state,
329	            &issuer,
330	        )
331	        .into_response();
332	    }
333	
334	    if params.code_challenge_method != "S256" {
335	        return error_redirect(
336	            &params.redirect_uri,
337	            "invalid_request",
338	            "code_challenge_method must be S256",
339	            &params.state,
340	            &issuer,
341	        )
342	        .into_response();
343	    }
