27	/// Form body for `POST /oauth/par` (application/x-www-form-urlencoded).
28	///
29	/// Accepts the same authorization request parameters as `GET /oauth/authorize`
30	/// so clients can push large parameter sets before sending the user to the auth endpoint.
31	#[derive(Debug, Deserialize)]
32	pub struct PARForm {
33	    pub client_id: Option<String>,
34	    pub redirect_uri: Option<String>,
35	    pub code_challenge: Option<String>,
36	    pub code_challenge_method: Option<String>,
37	    pub state: Option<String>,
38	    pub response_type: Option<String>,
39	    pub scope: Option<String>,
40	    pub login_hint: Option<String>,
41	}
