50	/// OAuth 2.0 error response (RFC 6749 §5.2 / RFC 9126 §2.3).
51	struct PARError {
52	    error: &'static str,
53	    error_description: String,
54	}
55	
56	impl PARError {
57	    fn new(error: &'static str, error_description: impl Into<String>) -> Self {
58	        Self {
59	            error,
60	            error_description: error_description.into(),
61	        }
62	    }
63	}
64	
65	impl IntoResponse for PARError {
66	    fn into_response(self) -> Response {
67	        let status = if self.error == "server_error" {
68	            StatusCode::INTERNAL_SERVER_ERROR
69	        } else {
70	            StatusCode::BAD_REQUEST
71	        };
72	        (
73	            status,
74	            Json(serde_json::json!({
75	                "error": self.error,
76	                "error_description": self.error_description,
77	            })),
78	        )
79	            .into_response()
80	    }
81	}
