83	// ── Redirect-URI policy ───────────────────────────────────────────────────────
84	
85	/// atproto OAuth: for a discoverable (URL) client_id, a private-use-scheme redirect
86	/// URI's scheme must be the client_id host's FQDN in reverse order (e.g. client_id
87	/// host `identitywallet.obsign.org` ⇒ scheme `org.obsign.identitywallet`). This binds
88	/// the custom scheme to a domain the client demonstrably controls — without it, any
89	/// app could register a metadata document listing another app's callback scheme.
90	///
91	/// The rule only applies to https client_ids (discoverable metadata): loopback-http
92	/// client_ids are the spec's local-development exception with no meaningful domain,
93	/// non-URL client_ids are operator-registered rows the rule predates, and http(s)
94	/// redirect URIs are not private-use schemes.
95	fn validate_private_use_redirect(client_id: &str, redirect_uri: &str) -> Result<(), String> {
96	    let Ok(client_url) = url::Url::parse(client_id) else {
97	        return Ok(());
98	    };
99	    if client_url.scheme() != "https" {
100	        return Ok(());
101	    }
102	    let Ok(redirect_url) = url::Url::parse(redirect_uri) else {
103	        return Ok(());
104	    };
105	    let scheme = redirect_url.scheme();
106	    if scheme == "http" || scheme == "https" {
107	        return Ok(());
108	    }
109	    let Some(host) = client_url.host_str() else {
110	        return Ok(());
111	    };
112	    let reversed = host.split('.').rev().collect::<Vec<_>>().join(".");
113	    if scheme.eq_ignore_ascii_case(&reversed) {
114	        Ok(())
115	    } else {
116	        Err(format!(
117	            "Private-Use URI Scheme redirect URI, for discoverable client metadata, \
118	             must be the fully qualified domain name (FQDN) of the client_id, \
119	             in reverse order ({reversed}:)"
120	        ))
121	    }
122	}
