124	// ── Handler ───────────────────────────────────────────────────────────────────
125	
126	/// `POST /oauth/par` — accept pushed authorization request parameters.
127	///
128	/// Clients POST their authorization parameters here first, receiving back an opaque
129	/// `request_uri` they then pass to `GET /oauth/authorize?request_uri=...`. This keeps
130	/// large payloads (DPoP key assertions, PKCE challenges) out of query strings and
131	/// browser history (RFC 9126).
132	pub async fn post_par(State(state): State<AppState>, Form(form): Form<PARForm>) -> Response {
133	    let client_id = match form.client_id.as_deref().filter(|s| !s.is_empty()) {
134	        Some(id) => id.to_string(),
135	        None => return PARError::new("invalid_request", "client_id is required").into_response(),
136	    };
137	
138	    let redirect_uri = match form.redirect_uri.as_deref().filter(|s| !s.is_empty()) {
139	        Some(u) => u.to_string(),
140	        None => {
141	            return PARError::new("invalid_request", "redirect_uri is required").into_response()
142	        }
143	    };
144	
145	    let code_challenge = match form.code_challenge.as_deref().filter(|s| !s.is_empty()) {
146	        Some(c) => c.to_string(),
147	        None => {
148	            return PARError::new("invalid_request", "code_challenge is required").into_response()
149	        }
150	    };
151	
152	    let code_challenge_method = match form
153	        .code_challenge_method
154	        .as_deref()
155	        .filter(|s| !s.is_empty())
156	    {
157	        Some(m) => m.to_string(),
158	        None => {
159	            return PARError::new("invalid_request", "code_challenge_method is required")
160	                .into_response()
161	        }
162	    };
163	
164	    let state_param = match form.state.as_deref().filter(|s| !s.is_empty()) {
165	        Some(s) => s.to_string(),
166	        None => return PARError::new("invalid_request", "state is required").into_response(),
167	    };
168	
169	    let response_type = match form.response_type.as_deref().filter(|s| !s.is_empty()) {
170	        Some(r) => r.to_string(),
171	        None => {
172	            return PARError::new("invalid_request", "response_type is required").into_response()
173	        }
174	    };
175	
176	    // Validate & canonically normalize the requested granular scopes; a malformed
177	    // or unsupported scope is rejected up-front (RFC 6749 §4.1.2.1 `invalid_scope`).
178	    let requested_scope = form
179	        .scope
180	        .as_deref()
181	        .filter(|s| !s.is_empty())
182	        .unwrap_or("atproto");
183	    let scope = match crate::auth::oauth_scopes::normalize_scope_request(requested_scope) {
184	        Ok(s) => s,
185	        Err(desc) => return PARError::new("invalid_scope", desc).into_response(),
186	    };
187	
188	    // Look up the client: registered/cached rows first; on a miss, a URL-shaped
189	    // client_id is resolved by fetching its metadata document (ATProto OAuth —
190	    // client_id IS the metadata URL). The fetched document is only cached below,
191	    // after the whole request validates.
192	    let known_client = match get_oauth_client(&state.db, &client_id).await {
193	        Ok(row) => row,
194	        Err(e) => {
195	            tracing::error!(error = %e, "db error looking up OAuth client in PAR");
196	            return PARError::new("server_error", "database error").into_response();
197	        }
198	    };
199	    let (client_metadata_json, freshly_fetched) = match known_client {
200	        Some(row) => (row.client_metadata, false),
201	        None if client_id.starts_with("https://") || client_id.starts_with("http://") => {
202	            match crate::auth::oauth_client_resolution::resolve_client_metadata(
203	                &state.http_client,
204	                &client_id,
205	            )
206	            .await
207	            {
208	                Ok(json) => (json, true),
209	                Err(e) => {
210	                    tracing::info!(client_id = %client_id, error = %e, "URL client_id resolution failed in PAR");
211	                    return PARError::new("invalid_client", e.to_string()).into_response();
212	                }
213	            }
214	        }
215	        None => {
216	            return PARError::new("invalid_client", "client_id is not registered").into_response()
217	        }
218	    };
219	
220	    let metadata: ClientMetadata = match serde_json::from_str(&client_metadata_json) {
221	        Ok(m) => m,
222	        Err(e) => {
223	            tracing::error!(
224	                client_id = %client_id,
225	                error = %e,
226	                "failed to parse stored client metadata in PAR"
227	            );
228	            return PARError::new("server_error", "client metadata is malformed").into_response();
229	        }
230	    };
231	
232	    if !metadata.redirect_uris.contains(&redirect_uri) {
233	        return PARError::new(
234	            "invalid_request",
235	            "redirect_uri does not match registered URIs",
236	        )
237	        .into_response();
238	    }
239	
240	    if let Err(desc) = validate_private_use_redirect(&client_id, &redirect_uri) {
241	        return PARError::new("invalid_redirect_uri", desc).into_response();
242	    }
243	
244	    if response_type != "code" {
245	        return PARError::new(
246	            "unsupported_response_type",
247	            "only response_type=code is supported",
248	        )
249	        .into_response();
250	    }
251	
252	    if code_challenge_method != "S256" {
253	        return PARError::new("invalid_request", "code_challenge_method must be S256")
254	            .into_response();
255	    }
256	
257	    let params = StoredPARParams {
258	        redirect_uri,
259	        code_challenge,
260	        code_challenge_method,
261	        state: state_param,
262	        response_type,
263	        scope,
264	        login_hint: form.login_hint.filter(|s| !s.is_empty()),
265	    };
266	
267	    let params_json = match serde_json::to_string(&params) {
268	        Ok(j) => j,
269	        Err(e) => {
270	            tracing::error!(client_id = %client_id, error = %e, "failed to serialize PAR params to JSON");
271	            return PARError::new("server_error", "failed to serialize request parameters")
272	                .into_response();
273	        }
274	    };
275	
276	    // The request has fully validated — now cache a freshly resolved metadata document
277	    // so the authorize/token endpoints' client lookups find it. Caching only after full
278	    // validation keeps rejected requests from planting rows.
279	    if freshly_fetched {
280	        if let Err(e) = upsert_oauth_client(&state.db, &client_id, &client_metadata_json).await {
281	            tracing::error!(error = %e, client_id = %client_id, "failed to cache resolved OAuth client metadata");
282	            return PARError::new("server_error", "database error").into_response();
283	        }
284	    }
285	
286	    // Generate the opaque request_uri token. The plaintext is used as the URN reference.
287	    let token = generate_token();
288	    let request_uri = format!("urn:ietf:params:oauth:request_uri:{}", token.plaintext);
289	
290	    if let Err(e) = store_par_request(&state.db, &request_uri, &client_id, &params_json).await {
291	        tracing::error!(error = %e, "failed to store PAR request");
292	        return PARError::new("server_error", "failed to store authorization request")
293	            .into_response();
294	    }
295	
296	    if let Err(e) = cleanup_expired_par_requests(&state.db).await {
297	        tracing::warn!(error = %e, "failed to cleanup expired PAR requests");
298	    }
299	
300	    (
301	        StatusCode::CREATED,
302	        Json(PARResponse {
303	            request_uri,
304	            expires_in: 60,
305	        }),
306	    )
307	        .into_response()
308	}
