328	    /// Build a form-urlencoded body for POST /oauth/par.
329	    ///
330	    /// Pass `overrides` to replace specific field values. Pass `("field", "")` to
331	    /// simulate a missing/empty required field.
332	    ///
333	    /// Note: values are NOT percent-encoded. Test data is chosen to contain only
334	    /// characters safe in form values (no `&`, `=`, `+`, `?`). Do not add test
335	    /// values that contain these characters without first encoding them.
336	    fn par_body(overrides: &[(&str, &str)]) -> String {
337	        let mut fields = vec![
338	            ("client_id", CLIENT_ID),
339	            ("redirect_uri", REDIRECT_URI),
340	            ("code_challenge", "abc123challengevalue"),
341	            ("code_challenge_method", "S256"),
342	            ("state", "state-value-xyz"),
343	            ("response_type", "code"),
344	            ("scope", "atproto"),
345	        ];
346	        for (k, v) in overrides {
347	            if let Some(pos) = fields.iter().position(|(fk, _)| fk == k) {
348	                fields[pos] = (k, v);
349	            } else {
350	                fields.push((k, v));
351	            }
352	        }
353	        fields
354	            .iter()
355	            .filter(|(_, v)| !v.is_empty()) // empty value = omit the field entirely
356	            .map(|(k, v)| format!("{}={}", k, v))
357	            .collect::<Vec<_>>()
358	            .join("&")
359	    }
