695	    /// Serve a client-metadata document at `/oauth/client-metadata.json` on an ephemeral
696	    /// loopback port; returns the document's URL (which doubles as the client_id). The JSON
697	    /// is produced by `make_json(url)` so the document can reference its own URL as
698	    /// `client_id`, mirroring a real ATProto OAuth client metadata document.
699	    async fn serve_client_metadata(make_json: impl FnOnce(&str) -> String) -> String {
700	        use std::future::IntoFuture;
701	
702	        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
703	        let url = format!(
704	            "http://127.0.0.1:{}/oauth/client-metadata.json",
705	            listener.local_addr().unwrap().port()
706	        );
707	        let json = make_json(&url);
708	        let router = axum::Router::new().route(
709	            "/oauth/client-metadata.json",
710	            axum::routing::get(move || {
711	                let json = json.clone();
712	                async move { ([("content-type", "application/json")], json) }
713	            }),
714	        );
715	        tokio::spawn(axum::serve(listener, router).into_future());
716	        url
717	    }
