// 1. Confirm live AS metadata basics; 2. replay rpg.actor's exact PAR request same-origin.
const meta = await (await fetch('/.well-known/oauth-authorization-server')).json();
const scope = "atproto repo:actor.rpg.stats repo:actor.rpg.sprite repo:actor.rpg.master repo:actor.rpg.generator repo:equipment.rpg.item repo:place.stream.chat.message repo:site.standard.document repo:site.standard.publication repo:games.atmosphere.define blob:image/*";
const body = new URLSearchParams({
  client_id: "https://rpg.actor/client-metadata.json",
  redirect_uri: "https://rpg.actor/oauth/callback",
  code_challenge: "REDACTED",
  code_challenge_method: "S256",
  state: "diag-state-123",
  response_type: "code",
  scope,
  login_hint: "malpercio.dev",
});
const par = await fetch('/oauth/par', {method:'POST', headers:{'content-type':'application/x-www-form-urlencoded'}, body: body.toString()});
const parBody = await par.text();
JSON.stringify({issuer: meta.issuer, par_required: meta.require_pushed_authorization_requests, parStatus: par.status, parBody: parBody.slice(0,500)});

