2	//
3	// The `authorization_code` grant (RFC 6749 §4.1 + PKCE RFC 7636 + DPoP RFC 9449): validate the
4	// DPoP proof at the token endpoint, verify the PKCE S256 challenge and client_id/redirect_uri
5	// against the stored authorization code, consume the code, then mint a DPoP-bound access token +
6	// rotating refresh token.
7	
8	use axum::{
9	    http::{HeaderMap, StatusCode},
10	    response::{IntoResponse, Response},
11	    Json,
12	};
13	use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
14	use sha2::{Digest, Sha256};
15	
16	use super::{
17	    cleanup_expired_state, issue_access_token, token_response_headers, TokenRequestForm,
18	    TokenResponse,
19	};
20	use crate::app::AppState;
21	use crate::auth::token::generate_token;
22	use crate::auth::{issue_nonce, validate_dpop_for_token_endpoint, DpopTokenEndpointError};
23	use crate::db::oauth::{
24	    delete_authorization_code, get_authorization_code, store_oauth_refresh_token,
25	};
26	use crate::routes::oauth_errors::OAuthTokenError;
