28	/// Verify the PKCE S256 code challenge.
29	fn verify_pkce_s256(code_verifier: &str, stored_challenge: &str) -> bool {
30	    let hash = Sha256::digest(code_verifier.as_bytes());
31	    let computed = URL_SAFE_NO_PAD.encode(hash);
32	    // Constant-time comparison to prevent timing oracle.
33	    subtle::ConstantTimeEq::ct_eq(computed.as_bytes(), stored_challenge.as_bytes()).into()
34	}
35	
36	pub(super) async fn handle_authorization_code(
37	    state: &AppState,
38	    headers: &HeaderMap,
39	    form: TokenRequestForm,
40	) -> Response {
41	    // Prune stale nonces and expired tokens on every request.
42	    cleanup_expired_state(state).await;
43	
44	    // Required fields: code, redirect_uri, client_id, code_verifier.
45	    let code = match form.code.as_deref() {
46	        Some(c) if !c.is_empty() => c,
47	        _ => {
48	            return OAuthTokenError::new("invalid_request", "missing parameter: code")
49	                .into_response()
50	        }
51	    };
52	    let redirect_uri = match form.redirect_uri.as_deref() {
53	        Some(u) if !u.is_empty() => u,
54	        _ => {
55	            return OAuthTokenError::new("invalid_request", "missing parameter: redirect_uri")
56	                .into_response()
57	        }
58	    };
59	    let client_id = match form.client_id.as_deref() {
60	        Some(id) if !id.is_empty() => id,
61	        _ => {
62	            return OAuthTokenError::new("invalid_request", "missing parameter: client_id")
63	                .into_response()
64	        }
65	    };
66	    let code_verifier = match form.code_verifier.as_deref() {
67	        Some(v) if !v.is_empty() => v,
68	        _ => {
69	            return OAuthTokenError::new("invalid_request", "missing parameter: code_verifier")
70	                .into_response()
71	        }
72	    };
73	
74	    // RFC 7636 §4.1: 43–128 unreserved characters [A-Za-z0-9\-._~] (F7).
75	    {
76	        const CV_UNRESERVED: fn(u8) -> bool =
77	            |b: u8| b.is_ascii_alphanumeric() || b == b'-' || b == b'.' || b == b'_' || b == b'~';
78	        if code_verifier.len() < 43
79	            || code_verifier.len() > 128
80	            || !code_verifier.bytes().all(CV_UNRESERVED)
81	        {
82	            return OAuthTokenError::new(
83	                "invalid_grant",
84	                "code_verifier must be 43–128 unreserved characters [A-Za-z0-9-._~]",
85	            )
86	            .into_response();
87	        }
88	    }
89	
90	    // Reject multiple DPoP headers (RFC 9449 §11.1).
91	    if headers.get_all("DPoP").iter().count() > 1 {
92	        return OAuthTokenError::new(
93	            "invalid_dpop_proof",
94	            "multiple DPoP headers are not permitted",
95	        )
96	        .into_response();
97	    }
98	
99	    // Validate DPoP proof.
100	    let dpop_token = match headers.get("DPoP").and_then(|v| v.to_str().ok()) {
101	        Some(t) => t.to_string(),
102	        None => {
103	            return OAuthTokenError::new("invalid_dpop_proof", "DPoP header required")
104	                .into_response();
105	        }
106	    };
107	
108	    let token_url = format!(
109	        "{}/oauth/token",
110	        state.config.public_url.trim_end_matches('/')
111	    );
112	
113	    let jkt =
114	        match validate_dpop_for_token_endpoint(&dpop_token, "POST", &token_url, &state.dpop_nonces)
115	            .await
116	        {
117	            Ok(jkt) => jkt,
118	            Err(DpopTokenEndpointError::MissingHeader) => {
119	                return OAuthTokenError::new("invalid_dpop_proof", "DPoP header required")
120	                    .into_response();
121	            }
122	            Err(DpopTokenEndpointError::InvalidProof(msg)) => {
123	                return OAuthTokenError::new("invalid_dpop_proof", msg).into_response();
124	            }
125	            Err(DpopTokenEndpointError::UseNonce(fresh_nonce)) => {
126	                return OAuthTokenError::with_nonce(
127	                    "use_dpop_nonce",
128	                    "DPoP nonce required",
129	                    fresh_nonce,
130	                )
131	                .into_response();
132	            }
133	        };
134	
135	    // Hash the presented code for DB lookup.
136	    let code_hash = match URL_SAFE_NO_PAD.decode(code) {
137	        Ok(bytes) => crate::auth::token::sha256_hex(&bytes),
138	        Err(_) => {
139	            return OAuthTokenError::new("invalid_grant", "authorization code invalid or expired")
140	                .into_response();
141	        }
142	    };
143	
144	    // Retrieve the authorization code (without consuming yet).
145	    let auth_code = match get_authorization_code(&state.db, &code_hash).await {
146	        Ok(Some(row)) => row,
147	        Ok(None) => {
148	            return OAuthTokenError::new("invalid_grant", "authorization code invalid or expired")
149	                .into_response();
150	        }
151	        Err(e) => {
152	            tracing::error!(error = %e, "failed to retrieve authorization code");
153	            return OAuthTokenError::new("server_error", "database error").into_response();
154	        }
155	    };
156	
157	    // Verify client_id matches before consuming.
158	    if auth_code.client_id != client_id {
159	        return OAuthTokenError::new("invalid_grant", "client_id mismatch").into_response();
160	    }
161	
162	    // Verify redirect_uri matches before consuming.
163	    if auth_code.redirect_uri != redirect_uri {
164	        return OAuthTokenError::new("invalid_grant", "redirect_uri mismatch").into_response();
165	    }
166	
167	    // Enforce S256: reject plain (or any other method) in case it ever enters the DB.
168	    if auth_code.code_challenge_method != "S256" {
169	        return OAuthTokenError::new("invalid_request", "unsupported code_challenge_method")
170	            .into_response();
171	    }
172	
173	    // Verify PKCE S256 challenge before consuming.
174	    if !verify_pkce_s256(code_verifier, &auth_code.code_challenge) {
175	        return OAuthTokenError::new(
176	            "invalid_grant",
177	            "code_verifier does not match code_challenge",
178	        )
179	        .into_response();
180	    }
181	
182	    // All validations passed; now consume the code.
183	    if let Err(e) = delete_authorization_code(&state.db, &code_hash).await {
184	        tracing::error!(error = %e, "failed to delete authorization code");
185	        return OAuthTokenError::new("server_error", "database error").into_response();
186	    }
187	
188	    // The access token carries the granular scope set granted at consent time verbatim —
189	    // `auth/oauth_scopes.rs` enforces it per route and `extractors.rs` reads the token's
190	    // scope claim on every authenticated request.
191	    let granted_scope = auth_code.scope;
192	
193	    // Issue ES256 access token.
194	    let access_token = match issue_access_token(
195	        &state.oauth_signing_keypair,
196	        &auth_code.did,
197	        &granted_scope,
198	        Some(&jkt),
199	        None,
200	        &state.config.public_url,
201	    ) {
202	        Ok(t) => t,
203	        Err(e) => return e.into_response(),
204	    };
205	
206	    // Generate and store refresh token, persisting the granted scope so rotation
207	    // carries it forward.
208	    let refresh = generate_token();
209	    if let Err(e) = store_oauth_refresh_token(
210	        &state.db,
211	        &refresh.hash,
212	        &auth_code.client_id,
213	        &auth_code.did,
214	        &granted_scope,
215	        &jkt,
216	    )
217	    .await
218	    {
219	        tracing::error!(error = %e, "failed to store refresh token");
220	        return OAuthTokenError::new("server_error", "database error").into_response();
221	    }
222	
223	    // Issue a fresh DPoP nonce for the next request.
224	    let fresh_nonce = issue_nonce(&state.dpop_nonces).await;
225	
226	    let response_headers = match token_response_headers(&fresh_nonce) {
227	        Ok(h) => h,
228	        Err(e) => return e.into_response(),
229	    };
230	
231	    (
232	        StatusCode::OK,
233	        response_headers,
234	        Json(TokenResponse {
235	            access_token,
236	            token_type: "DPoP",
237	            expires_in: 300,
238	            refresh_token: refresh.plaintext,
239	            scope: granted_scope,
240	            sub: auth_code.did,
241	        }),
242	    )
243	        .into_response()
244	}
