1	// pattern: Functional Core
2	//
3	// Pure rendering functions for the OAuth consent UI. All inputs are plain data; all
4	// outputs are plain strings or Axum response types that carry no side effects.
5	// No I/O, no database, no AppState.
6	//
7	// Visual system: "The Sealed Credential" (see DESIGN.md). Brand fonts are served by the
8	// the PDS's own /static/fonts route (no third-party CDN — an auth page must not leak logins).
9	
10	use axum::http::StatusCode;
11	use axum::response::{Html, Redirect};
12	
13	// ── Public rendering functions ────────────────────────────────────────────────
14	
15	/// Build an OAuth error redirect (303) to `redirect_uri` with error parameters.
16	///
17	/// `issuer` is emitted as the RFC 9207 `iss` parameter. The AT Protocol OAuth metadata
18	/// advertises `authorization_response_iss_parameter_supported: true`, so a conformant
19	/// client validates `iss` on every authorization response — including error responses
20	/// (e.g. the user denying) — and rejects one that omits it.
21	pub(super) fn error_redirect(
22	    redirect_uri: &str,
23	    error: &str,
24	    description: &str,
25	    state: &str,
26	    issuer: &str,
27	) -> Redirect {
28	    let sep = if redirect_uri.contains('?') { '&' } else { '?' };
29	    let url = format!(
30	        "{}{}error={}&error_description={}&state={}&iss={}",
31	        redirect_uri,
32	        sep,
33	        encode_param(error),
34	        encode_param(description),
35	        encode_param(state),
36	        encode_param(issuer),
37	    );
38	    Redirect::to(&url)
39	}
