41	/// Render a standalone HTML error page for cases where redirecting is unsafe
42	/// (unknown `client_id`, mismatched `redirect_uri`).
43	pub(super) fn error_page(title: &str, message: &str) -> (StatusCode, Html<String>) {
44	    let mut html = String::with_capacity(2048);
45	    html.push_str(ERROR_PAGE_HEADER);
46	    html.push_str(&html_escape(title));
47	    html.push_str("</title>\n  <style>");
48	    html.push_str(FONT_FACES);
49	    html.push_str(ERROR_CSS);
50	    html.push_str("  </style>\n</head>\n<body>\n");
51	    html.push_str(
52	        "  <div class=\"card\">\n    <div class=\"top\">\n      <span class=\"seal alarm\">",
53	    );
54	    html.push_str(ICON_ALARM);
55	    html.push_str("</span>\n      <h1>");
56	    html.push_str(&html_escape(title));
57	    html.push_str("</h1>\n      <p class=\"err-msg\">");
58	    html.push_str(&html_escape(message));
59	    html.push_str("</p>\n    </div>\n  </div>\n</body>\n</html>");
60	    (StatusCode::BAD_REQUEST, Html(html))
61	}
