63	/// Build an authorization-code success redirect (303) back to the client, carrying the plaintext
64	/// `code`, the round-tripped `state`, and the RFC 9207 `iss` parameter. Shared by the password
65	/// consent path and the wallet-completion path so both emit byte-identical responses.
66	pub(super) fn build_code_redirect(
67	    redirect_uri: &str,
68	    code: &str,
69	    state: &str,
70	    issuer: &str,
71	) -> Redirect {
72	    let sep = if redirect_uri.contains('?') { '&' } else { '?' };
73	    let url = format!(
74	        "{}{}code={}&state={}&iss={}",
75	        redirect_uri,
76	        sep,
77	        encode_param(code),
78	        encode_param(state),
79	        encode_param(issuer),
80	    );
81	    Redirect::to(&url)
82	}
