84	/// The wallet-path data the consent page renders alongside the password form: the pending
85	/// request's high-entropy `request_id` (poll key + handoff/complete linkage), its human-typeable
86	/// `user_code`, and the requesting `origin` (snapshotted on creation, encoded into the scan QR
87	/// alongside the `request_id`). Present only when the GET handler created a pending request.
88	pub(super) struct WalletConsentPath<'a> {
89	    pub user_code: &'a str,
90	    pub request_id: &'a str,
91	    pub origin: Option<&'a str>,
92	}
