94	/// Custom URL scheme the identity wallet registers; the "Open in Obsign" handoff link targets it.
95	/// The wallet has no deep-link handler yet (ADR-0006 removed server-initiated redirects), so this
96	/// link may degrade to "copy the code" — the typed `user_code` is the guaranteed path.
97	const WALLET_HANDOFF_SCHEME: &str = "org.obsign.identitywallet";
