99	/// Render the OAuth consent + sign-in page.
100	///
101	/// All user-controlled values are HTML-escaped before insertion.
102	/// `login_hint` pre-populates the identifier field (from the ATProto `login_hint` param
103	/// or from a previous failed submission so the user can correct their handle).
104	/// `error` renders an error banner above the form when credential validation fails.
105	/// `wallet` renders the wallet-approval path (typed code + handoff link + status polling) above
106	/// the password form; `None` on a password-error re-render, where no pending request exists.
107	#[allow(clippy::too_many_arguments)]
108	pub(super) fn render_consent_page(
109	    client_name: &str,
110	    client_id: &str,
111	    redirect_uri: &str,
112	    code_challenge: &str,
113	    code_challenge_method: &str,
114	    state: &str,
115	    scope: &str,
116	    response_type: &str,
117	    public_url: &str,
118	    login_hint: Option<&str>,
119	    error: Option<&str>,
120	    wallet: Option<&WalletConsentPath>,
121	) -> String {
122	    // Monogram for the application mark — the first character of the client name.
123	    let app_initial = client_name
124	        .chars()
125	        .next()
126	        .map(|c| c.to_uppercase().to_string())
127	        .unwrap_or_else(|| "·".to_string());
128	
129	    // Build HTML by concatenation — avoids doubling all CSS braces for format!.
130	    let mut html = String::with_capacity(6144);
131	    html.push_str(CONSENT_PAGE_HEADER);
132	    html.push_str(FONT_FACES);
133	    html.push_str(CONSENT_CSS);
134	    html.push_str("  </style>\n</head>\n<body>\n");
135	    html.push_str("  <div class=\"card\">\n");
136	
137	    // Header: seal, title, subtitle.
138	    html.push_str("    <div class=\"top\">\n      <span class=\"seal\">");
139	    html.push_str(ICON_SEAL_LG);
140	    html.push_str("</span>\n      <h1>Authorize access</h1>\n");
141	    html.push_str("      <p class=\"sub\">An app wants to sign in as your identity. Review the request, then approve to continue.</p>\n    </div>\n");
142	    html.push_str("    <div class=\"rule\"></div>\n");
143	
144	    // Application.
145	    html.push_str("    <div class=\"section-label\">Application</div>\n");
146	    html.push_str("    <div class=\"app\">\n      <span class=\"app-mark\">");
147	    html.push_str(&html_escape(&app_initial));
148	    html.push_str("</span>\n      <span>\n        <div class=\"client-name\">");
149	    html.push_str(&html_escape(client_name));
150	    html.push_str("</div>\n        <div class=\"client-id\">");
151	    html.push_str(&html_escape(client_id));
152	    html.push_str("</div>\n      </span>\n    </div>\n");
153	
154	    // Wallet path: shown first because it is the primary path for sovereign / passwordless
155	    // accounts (which cannot use the password form at all). Scope reduction moves into the wallet
156	    // for this path — the granted set is chosen there, not with the checkboxes below.
157	    if let Some(w) = wallet {
158	        html.push_str(&render_wallet_path(w));
159	        html.push_str("    <div class=\"divider\"><span>or sign in with a password</span></div>\n");
160	    }
161	
162	    // The <form> opens BEFORE the permissions section: the `granted_scope` checkboxes
163	    // must be form members or the browser silently omits them from the POST, and the
164	    // consent reduction filter would strip every non-`atproto` grant the user approved.
165	    html.push_str("    <form method=\"POST\" action=\"/oauth/authorize\">\n");
166	
167	    // Permissions: `atproto` is the mandatory base — always granted, never a checkbox.
168	    // Everything else is grouped by resource type with a checked-by-default checkbox, so the
169	    // user can deny individual permissions before approving.
170	    html.push_str("    <div class=\"section-label\">Base access</div>\n");
171	    html.push_str(
172	        "    <div class=\"scopes\">\n        <span class=\"scope-tag\">atproto</span>\n    </div>\n",
173	    );
174	    html.push_str(&render_permission_groups(scope));
175	    html.push_str("    <p class=\"scope-note\">Uncheck anything you don't want to grant — the app will only be able to do what's left checked.</p>\n");
176	
177	    // Sign in.
178	    html.push_str("    <div class=\"section-label\">Sign in to approve</div>\n");
179	    if let Some(msg) = error {
180	        html.push_str("    <div class=\"error-banner\">");
181	        html.push_str(ICON_ALERT);
182	        html.push_str("<span>");
183	        html.push_str(&html_escape(msg));
184	        html.push_str("</span></div>\n");
185	    }
186	    for (name, value) in [
187	        ("client_id", client_id),
188	        ("redirect_uri", redirect_uri),
189	        ("code_challenge", code_challenge),
190	        ("code_challenge_method", code_challenge_method),
191	        ("state", state),
192	        ("scope", scope),
193	        ("response_type", response_type),
194	    ] {
195	        html.push_str(&format!(
196	            "      <input type=\"hidden\" name=\"{}\" value=\"{}\" />\n",
197	            name,
198	            html_escape(value)
199	        ));
200	    }
201	    // autocapitalize/autocorrect/spellcheck are all disabled: handles and DIDs are
202	    // case-sensitive, lowercase identifiers, so iOS's default first-letter capitalization
203	    // (and autocorrect) would silently mangle a typed identifier and break sign-in.
204	    html.push_str(&format!(
205	        "      <input type=\"text\" name=\"identifier\" placeholder=\"alice.bsky.social or did:plc:…\" \
206	         autocomplete=\"username\" autocapitalize=\"none\" autocorrect=\"off\" spellcheck=\"false\" \
207	         value=\"{}\" class=\"field mono\" />\n",
208	        html_escape(login_hint.unwrap_or(""))
209	    ));
210	    html.push_str(
211	        "      <input type=\"password\" name=\"password\" placeholder=\"Password\" \
212	         autocomplete=\"current-password\" class=\"field\" />\n",
213	    );
214	    html.push_str("      <div class=\"actions\">\n");
215	    html.push_str("        <button type=\"submit\" name=\"action\" value=\"deny\" class=\"btn btn-deny\">Deny</button>\n");
216	    html.push_str("        <button type=\"submit\" name=\"action\" value=\"approve\" class=\"btn btn-approve\">");
217	    html.push_str(ICON_SEAL_SM);
218	    html.push_str("Approve</button>\n");
219	    html.push_str("      </div>\n    </form>\n");
220	
221	    // Footer: which PDS is serving this page.
222	    html.push_str("    <div class=\"server-info\">");
223	    html.push_str(ICON_LOCK);
224	    html.push_str("<span>");
225	    html.push_str(&html_escape(public_url));
226	    html.push_str("</span></div>\n  </div>\n</body>\n</html>");
227	    html
228	}
