231	
232	/// Render every non-`atproto` scope token as a checked-by-default checkbox, grouped under a
233	/// resource-type heading. `atproto` is rendered separately by the caller — it's mandatory and
234	/// never a checkbox.
235	fn render_permission_groups(scope: &str) -> String {
236	    let mut groups: Vec<(&'static str, Vec<&str>)> = Vec::new();
237	    for token in scope.split_whitespace() {
238	        if token == "atproto" {
239	            continue;
240	        }
241	        let label = crate::auth::oauth_scopes::resource_group_label(token);
242	        match groups.iter_mut().find(|(l, _)| *l == label) {
243	            Some((_, tokens)) => tokens.push(token),
244	            None => groups.push((label, vec![token])),
245	        }
246	    }
247	
248	    let mut html = String::new();
249	    for (label, tokens) in groups {
250	        html.push_str("    <div class=\"section-label\">");
251	        html.push_str(&html_escape(label));
252	        html.push_str("</div>\n    <div class=\"permission-group\">\n");
253	        for token in tokens {
254	            let escaped = html_escape(token);
255	            html.push_str(&format!(
256	                "      <label class=\"permission-row\"><input type=\"checkbox\" name=\"granted_scope\" value=\"{escaped}\" checked /> <span class=\"mono\">{escaped}</span></label>\n"
257	            ));
258	        }
259	        html.push_str("    </div>\n");
260	    }
261	    html
262	}
