266	/// The scan-QR / handoff payload: the wallet's private-use scheme carrying the pending request's
267	/// `request_id` and (informationally) the requesting `origin`. The wallet resolves and displays the
268	/// request **server-side by `request_id`** (it never trusts the QR contents for what it shows), so
269	/// the origin here is a snapshot for context/debugging only. The same string backs both the QR the
270	/// phone scans and the same-device "Open in Obsign" link.
271	fn wallet_handoff_uri(request_id: &str, origin: Option<&str>) -> String {
272	    let mut uri = format!(
273	        "{WALLET_HANDOFF_SCHEME}:/consent?request_id={}",
274	        encode_param(request_id)
275	    );
276	    if let Some(origin) = origin {
277	        uri.push_str("&origin=");
278	        uri.push_str(&encode_param(origin));
279	    }
280	    uri
281	}
