283	/// Render the wallet-approval block: a scan QR encoding the `request_id` (+ origin) for the
284	/// cross-device phone-scan path, the human-typeable `user_code` fallback (no camera / accessibility),
285	/// an "Open in Obsign" handoff link carrying the same payload for the same-device path, a live status
286	/// region, and a no-JS "I've approved — continue" form that POSTs to `/oauth/authorize/complete`. An
287	/// inline script polls `GET /oauth/authorize/status` (backing off on the `slow_down` 429) and, on
288	/// approval, submits the same completion form — so JS and no-JS reach the identical completion path.
289	fn render_wallet_path(w: &WalletConsentPath) -> String {
290	    let request_id = html_escape(w.request_id);
291	    let user_code = html_escape(w.user_code);
292	    let handoff = wallet_handoff_uri(w.request_id, w.origin);
293	    let mut html = String::with_capacity(2048);
294	    html.push_str("    <div class=\"section-label\">Approve in your wallet</div>\n");
295	    html.push_str("    <div class=\"wallet\" id=\"wallet-path\" data-request-id=\"");
296	    html.push_str(&request_id);
297	    html.push_str("\">\n");
298	    // Scan path first: the strongest cross-device channel (start from the page, no transcription).
299	    // Rendered only when the payload actually fits in a QR — otherwise the typed code below stands
300	    // in, and nothing about the fallback changes.
301	    if let Some(qr) = render_qr_svg(&handoff) {
302	        html.push_str(
303	            "      <p class=\"wallet-lead\">Scan this with Obsign on your phone to sign in with your device key:</p>\n",
304	        );
305	        html.push_str("      <div class=\"qr\">");
306	        html.push_str(&qr);
307	        html.push_str("</div>\n");
308	        html.push_str(
309	            "      <p class=\"wallet-lead wallet-or\">No camera? Open Obsign and enter this code:</p>\n",
310	        );
311	    } else {
312	        html.push_str(
313	            "      <p class=\"wallet-lead\">Open Obsign and enter this code to sign in with your device key:</p>\n",
314	        );
315	    }
316	    html.push_str("      <div class=\"user-code mono\">");
317	    html.push_str(&user_code);
318	    html.push_str("</div>\n");
319	    html.push_str("      <a class=\"btn btn-approve wallet-open\" href=\"");
320	    html.push_str(&html_escape(&handoff));
321	    html.push_str("\">");
322	    html.push_str(ICON_SEAL_SM);
323	    html.push_str("Open in Obsign</a>\n");
324	    html.push_str(
325	        "      <p class=\"wallet-status\" id=\"wallet-status\" role=\"status\" aria-live=\"polite\">Waiting for approval in your wallet…</p>\n",
326	    );
327	    html.push_str(
328	        "      <form method=\"POST\" action=\"/oauth/authorize/complete\" id=\"complete-form\">\n",
329	    );
330	    html.push_str("        <input type=\"hidden\" name=\"request_id\" value=\"");
331	    html.push_str(&request_id);
332	    html.push_str("\" />\n");
333	    html.push_str(
334	        "        <button type=\"submit\" class=\"btn btn-deny wallet-continue\">I've approved — continue</button>\n",
335	    );
336	    html.push_str("      </form>\n");
337	    html.push_str("    </div>\n");
338	    html.push_str(WALLET_POLL_SCRIPT);
339	    html
340	}
