342	/// Inline poller for the wallet path. Reads the `request_id` from the block's data attribute, polls
343	/// the status endpoint on a backoff that widens when it sees the `slow_down` 429, and submits the
344	/// completion form on approval. If CSP or a JS-off client blocks it, the no-JS continue button is
345	/// the fallback — the whole flow still completes.
346	const WALLET_POLL_SCRIPT: &str = r#"    <script>
347	    (function(){
348	      var el=document.getElementById('wallet-path');
349	      if(!el)return;
350	      var rid=el.getAttribute('data-request-id');
351	      var status=document.getElementById('wallet-status');
352	      var form=document.getElementById('complete-form');
353	      var interval=3000;
354	      function schedule(){setTimeout(poll,interval);}
355	      function poll(){
356	        fetch('/oauth/authorize/status?request_id='+encodeURIComponent(rid),{headers:{'Accept':'application/json'}})
357	          .then(function(r){
358	            if(r.status===429){interval=Math.min(interval+2000,15000);schedule();return null;}
359	            return r.json();
360	          })
361	          .then(function(d){
362	            if(!d)return;
363	            if(d.status==='approved'){status.textContent='Approved — continuing…';form.submit();return;}
364	            if(d.status==='denied'){status.textContent='This request was denied in your wallet.';return;}
365	            if(d.status==='expired'){status.textContent='This request expired. Reload the page to try again.';return;}
366	            if(d.status==='completed'){return;}
367	            schedule();
368	          })
369	          .catch(function(){schedule();});
370	      }
371	      schedule();
372	    })();
373	    </script>
374	"#;
