378	/// Percent-encode a string for safe inclusion as a URL query parameter value.
379	pub(super) fn encode_param(s: &str) -> String {
380	    let mut out = String::with_capacity(s.len());
381	    for b in s.bytes() {
382	        match b {
383	            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
384	                out.push(b as char)
385	            }
386	            _ => out.push_str(&format!("%{b:02X}")),
387	        }
388	    }
389	    out
390	}
391	
392	/// Render `data` as an inline, self-contained SVG QR code, or `None` if it does not fit in a QR
393	/// (the caller then falls back to the typed code, never breaking the page). Dark modules are drawn
394	/// as one `<path>` on a white ground with a 4-module quiet zone — dark-on-light with a fixed white
395	/// background so it scans regardless of the viewer's page theme. Pure: no I/O, deterministic.
396	fn render_qr_svg(data: &str) -> Option<String> {
397	    // Medium error correction balances density against scan robustness on a phone camera.
398	    let qr = qrcodegen::QrCode::encode_text(data, qrcodegen::QrCodeEcc::Medium).ok()?;
399	    const QUIET: i32 = 4;
400	    let size = qr.size();
401	    let dim = size + 2 * QUIET;
402	
403	    // One path of "M{x} {y}h1v1h-1z" per dark module — compact and crisp at any rendered size.
404	    use std::fmt::Write as _;
405	    let mut modules = String::new();
406	    for y in 0..size {
407	        for x in 0..size {
408	            if qr.get_module(x, y) {
409	                let _ = write!(modules, "M{} {}h1v1h-1z", x + QUIET, y + QUIET);
410	            }
411	        }
412	    }
413	
414	    Some(format!(
415	        "<svg viewBox=\"0 0 {dim} {dim}\" width=\"196\" height=\"196\" role=\"img\" \
416	         aria-label=\"QR code to sign in with the Obsign wallet\" \
417	         xmlns=\"http://www.w3.org/2000/svg\" shape-rendering=\"crispEdges\">\
418	         <rect width=\"{dim}\" height=\"{dim}\" fill=\"#ffffff\"/>\
419	         <path d=\"{modules}\" fill=\"#1b1b1f\"/></svg>"
420	    ))
421	}
