1	// pattern: Functional Core
2	//
3	// The shared OAuth 2.0 error response type for the token-issuing and token-revocation
4	// endpoints. Pure: given an error code, description, and optional DPoP nonce it builds an
5	// Axum response; no I/O, no database, no AppState. Lives here (rather than in either
6	// handler) so `oauth_token.rs` and `oauth_revoke.rs` share one responder without a
7	// route→route import — the same pattern as `oauth_templates.rs`.
8	
9	use axum::{
10	    http::StatusCode,
11	    response::{IntoResponse, Json, Response},
12	};
13	
14	/// OAuth 2.0 error response body (RFC 6749 §5.2).
15	///
16	/// All token-endpoint and revocation-endpoint errors use this format, distinct from the
17	/// codebase's `ApiError` envelope (`{ "error": { "code": "...", "message": "..." } }`).
18	pub(super) struct OAuthTokenError {
19	    pub error: &'static str,
20	    pub error_description: &'static str,
21	    /// Optional DPoP-Nonce value to include in the response header.
22	    /// Required for `use_dpop_nonce` errors so the client can retry.
23	    pub dpop_nonce: Option<String>,
24	}
25	
26	impl OAuthTokenError {
27	    pub(super) fn new(error: &'static str, error_description: &'static str) -> Self {
28	        Self {
29	            error,
30	            error_description,
31	            dpop_nonce: None,
32	        }
33	    }
34	
35	    pub(super) fn with_nonce(
36	        error: &'static str,
37	        error_description: &'static str,
38	        nonce: String,
39	    ) -> Self {
40	        Self {
41	            error,
42	            error_description,
43	            dpop_nonce: Some(nonce),
44	        }
45	    }
46	}
47	
48	impl IntoResponse for OAuthTokenError {
49	    fn into_response(self) -> Response {
50	        let body = serde_json::json!({
51	            "error": self.error,
52	            "error_description": self.error_description,
53	        });
54	        let mut headers = axum::http::HeaderMap::new();
55	        headers.insert(
56	            axum::http::header::CONTENT_TYPE,
57	            axum::http::HeaderValue::from_static("application/json"),
58	        );
59	        if let Some(nonce) = self.dpop_nonce {
60	            match axum::http::HeaderValue::from_str(&nonce) {
61	                Ok(hval) => {
62	                    headers.insert("DPoP-Nonce", hval);
63	                }
64	                Err(e) => {
65	                    // This should never happen: nonces are base64url ASCII, always valid
66	                    // header values. If it does happen, returning use_dpop_nonce without
67	                    // the nonce header leaves the client with no retry path (RFC 9449 §7.1).
68	                    // Return server_error instead.
69	                    tracing::error!(nonce = ?nonce, error = %e, "nonce string cannot be encoded as HTTP header value; this is a server bug");
70	                    return (
71	                        StatusCode::INTERNAL_SERVER_ERROR,
72	                        [(
73	                            axum::http::header::CONTENT_TYPE,
74	                            axum::http::HeaderValue::from_static("application/json"),
75	                        )],
76	                        Json(serde_json::json!({
77	                            "error": "server_error",
78	                            "error_description": "internal server error",
79	                        })),
80	                    )
81	                        .into_response();
82	                }
83	            }
84	        }
85	
86	        // RFC 6749 §5.2: most errors are 400, but server_error is 500.
87	        let status = if self.error == "server_error" {
88	            StatusCode::INTERNAL_SERVER_ERROR
89	        } else {
90	            StatusCode::BAD_REQUEST
91	        };
92	        (status, headers, Json(body)).into_response()
93	    }
94	}
